import subprocess
import os
import time
import glob
def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    """
    Executes an R script and verifies if the output file is generated within a given duration.

    Args:
        r_script_path (str): The path to the R script to be executed.
        output_path (str): The path or glob pattern of the output file to check for.
        duration (int): The maximum time (in seconds) to wait for the file generation.

    Returns:
        tuple: (bool, str)
            - bool: True if the output file is generated within the specified duration, False otherwise.
            - str: A message indicating the result of the operation.
    """
    # Check if the R script exists before attempting to run it
    if not os.path.exists(r_script_path):
        return (False, 'File not generated within the specified duration.')

    try:
        # Start the R script process
        # We use subprocess.Popen to run it in the background so we can poll the filesystem
        process = subprocess.Popen(['Rscript', r_script_path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception:
        return (False, 'File not generated within the specified duration.')

    start_time = time.time()

    # Poll for the existence of the output file until the duration expires
    while time.time() - start_time < duration:
        # glob.glob is used to support both specific paths and pattern matching
        if glob.glob(output_path):
            # If the file is found, we can return immediately
            return (True, 'File generated successfully within the specified duration.')

        # Short sleep to prevent a busy-wait loop that consumes excessive CPU
        time.sleep(0.5)

    # Final check after the loop to account for files created at the very last moment
    if glob.glob(output_path):
        return (True, 'File generated successfully within the specified duration.')

    # If the process is still running after the duration, we could optionally terminate it,
    # but the requirement only specifies checking for the file.
    return (False, 'File not generated within the specified duration.')

import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    """
    Compresses all files in the source folder using 'gzip' and moves them to a destination folder.

    Args:
        src_folder (str): The path to the source directory containing files to compress.
        dst_folder (str): The path to the destination directory where compressed files will be moved.

    Returns:
        dict: A dictionary containing the success status, a descriptive message, and a list of failed files.
    """
    # Ensure destination folder exists
    if not os.path.exists(dst_folder):
        try:
            os.makedirs(dst_folder)
        except Exception as e:
            return {
                'success': False,
                'message': f"Failed to create destination folder: {str(e)}",
                'failed_files': []
            }

    # Verify source folder exists
    if not os.path.exists(src_folder):
        return {
            'success': False,
            'message': "Source folder does not exist.",
            'failed_files': []
        }

    # Identify all files in the source folder (non-recursive)
    files = [f for f in glob(os.path.join(src_folder, '*')) if os.path.isfile(f)]
    failed_files = []

    if not files:
        return {
            'success': True,
            'message': "No files found in the source folder to compress.",
            'failed_files': []
        }

    for file_path in files:
        filename = os.path.basename(file_path)
        try:
            # Execute gzip as a subprocess. 
            # By default, gzip compresses the file and replaces it with 'filename.gz'.
            # '-f' is used to force compression even if the .gz file already exists.
            # subprocess.run waits for the command to complete (synchronous execution of background process).
            result = subprocess.run(['gzip', '-f', file_path], capture_output=True, text=True)

            if result.returncode == 0:
                # The expected compressed file path
                gz_src_path = file_path + '.gz'
                gz_filename = os.path.basename(gz_src_path)
                gz_dst_path = os.path.join(dst_folder, gz_filename)

                # Move the compressed file to the destination folder
                shutil.move(gz_src_path, gz_dst_path)
            else:
                failed_files.append(filename)
        except Exception:
            # Catch errors in subprocess execution or file moving
            failed_files.append(filename)

    success = len(failed_files) == 0
    if success:
        message = "All files were compressed and moved successfully."
    else:
        message = f"Operation completed, but {len(failed_files)} file(s) failed to process."

    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }
